//! Allowlist lock generator and reader (lock.rs). The committed fixtures in tests/allowlist were written by an
//! independent generator (Python hashlib), so byte equality here cross-checks lock.rs + AWS-LC SHA-256 against it.
//! `every_committed_declaration_in_the_repo_regenerates` walks the repository, so a lock committed anywhere (for
//! example apps/notes) is also regenerated by the production library, not only by `cargo xtask allowlist-lock`.

use monban_data_ir::*;
use monban_types::TenantId;
use std::path::{Path, PathBuf};

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join("allowlist")
}

fn read(p: &Path) -> String {
    std::fs::read_to_string(p).unwrap_or_else(|e| unreachable!("{}: {e}", p.display()))
}

fn pair(adapter: &str) -> (String, String) {
    let d = fixtures();
    (read(&d.join(format!("allowlist.{adapter}.decl"))), read(&d.join(format!("allowlist.{adapter}.lock"))))
}

const ADAPTERS: [&str; 3] = ["notes-sqlite", "notes-pg", "notes-kv"];

#[test]
fn sha256_known_answers() {
    assert_eq!(sha256_hex(b""), "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
    assert_eq!(sha256_hex(b"abc"), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");
}

#[test]
fn fixtures_regenerate_byte_identically() {
    for a in ADAPTERS {
        let (decl, lock) = pair(a);
        assert_eq!(generate(&decl).as_deref(), Ok(lock.as_str()), "{a}");
        assert_eq!(generate(&decl), generate(&decl));
        assert_eq!(verify(&decl, &lock), Ok(()));
        let Ok(al) = Allowlist::parse(&lock) else { unreachable!("{a}") };
        assert_eq!(al.adapter(), a);
        assert!(!al.is_empty());
        let d = parse_decl(&decl).unwrap_or_else(|e| unreachable!("{e:?}"));
        assert_eq!((d.adapter(), d.entries().len() >= al.len()), (a, true));
    }
}

fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(rd) = std::fs::read_dir(dir) else { return };
    for e in rd.flatten() {
        let p = e.path();
        let name = e.file_name().to_string_lossy().into_owned();
        if p.is_dir() {
            if !matches!(name.as_str(), "target" | ".git" | ".claude" | ".lake" | "node_modules") {
                walk(&p, out);
            }
        } else if name.starts_with("allowlist.") && (name.ends_with(".decl") || name.ends_with(".lock")) {
            out.push(p);
        }
    }
}

#[test]
fn every_committed_declaration_in_the_repo_regenerates() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("..");
    let mut files = Vec::new();
    walk(&root, &mut files);
    let mut pairs = 0;
    for f in &files {
        let name = f.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
        let Some(adapter) = name.strip_prefix("allowlist.").and_then(|n| n.strip_suffix(".decl")) else { continue };
        let lock = f.with_file_name(format!("allowlist.{adapter}.lock"));
        assert!(lock.is_file(), "{} has no lock", f.display());
        let decl = read(f);
        assert_eq!(verify(&decl, &read(&lock)), Ok(()), "{}", f.display());
        assert_eq!(parse_decl(&decl).map(|d| d.adapter().to_string()), Ok(adapter.to_string()));
        pairs += 1;
    }
    for f in &files {
        let name = f.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
        if let Some(adapter) = name.strip_prefix("allowlist.").and_then(|n| n.strip_suffix(".lock")) {
            assert!(f.with_file_name(format!("allowlist.{adapter}.decl")).is_file(), "orphan lock {}", f.display());
        }
    }
    assert!(pairs >= ADAPTERS.len(), "found {pairs} declaration/lock pairs");
}

#[test]
fn declaration_order_and_comments_do_not_matter() {
    let (decl, lock) = pair("notes-sqlite");
    let mut lines: Vec<&str> = decl.lines().collect();
    let tail = lines.split_off(3);
    let mut tail: Vec<&str> = tail.into_iter().filter(|l| !l.is_empty() && !l.starts_with('#')).collect();
    tail.reverse();
    let mut shuffled = lines.join("\n");
    shuffled.push_str("\n# a comment\n\n");
    shuffled.push_str(&tail.join("\n"));
    shuffled.push('\n');
    shuffled.push_str("op notes select eq(1) w=- r=3,2,1\n"); // duplicate after canonicalization
    assert_eq!(generate(&shuffled).as_deref(), Ok(lock.as_str()));
}

#[test]
fn mutated_declaration_or_lock_is_refused() {
    let (decl, lock) = pair("notes-sqlite");
    let stale = |d: &str| verify(d, &lock).map_err(|e| e.kind);
    assert_eq!(stale(&decl.replace("r=1,2,3\n", "r=1,2\n")), Err(DeclErrorKind::Stale));
    assert_eq!(stale(&format!("{decl}op notes delete pfx(2) w=- r=-\n")), Err(DeclErrorKind::Stale));
    assert_eq!(stale(&decl.replace("op notes delete eq(1) w=- r=-\n", "")), Err(DeclErrorKind::Stale));
    assert_eq!(stale(&decl.replace("adapter notes-sqlite", "adapter notes-sqlite2")), Err(DeclErrorKind::Stale));
    assert_eq!(stale(&decl.replace("family sqlite", "family postgres")), Err(DeclErrorKind::Stale));

    let flipped = lock.replacen("select", "selecu", 1);
    assert_eq!(verify(&decl, &flipped).map_err(|e| e.kind), Err(DeclErrorKind::Stale));
    assert_eq!(Allowlist::parse(&flipped), Err(LockFileError::Hash));
    let crlf = lock.replace('\n', "\r\n");
    assert!(Allowlist::parse(&crlf).is_err());
    assert!(Allowlist::parse(&format!("{lock}\n")).is_err());
    assert!(Allowlist::parse(lock.trim_end_matches('\n')).is_err());
    assert_eq!(Allowlist::parse(""), Err(LockFileError::NotCanonical));
    // Reordered body with a recomputed (valid) hash: refused as not canonical.
    let body_end = lock.rfind("sha256 ").unwrap_or(0);
    let body = lock.get(..body_end).unwrap_or("");
    let mut ls: Vec<&str> = body.lines().collect();
    let n = ls.len();
    ls.swap(n - 1, n - 2);
    let body2 = format!("{}\n", ls.join("\n"));
    let reordered = format!("{body2}sha256 {}\n", sha256_hex(body2.as_bytes()));
    assert_eq!(Allowlist::parse(&reordered), Err(LockFileError::NotCanonical));
    // Non-canonical entry text (unsorted field list) with a valid hash.
    let body3 = body.replace("r=1,2,3", "r=3,2,1");
    let noncanon = format!("{body3}sha256 {}\n", sha256_hex(body3.as_bytes()));
    assert_eq!(Allowlist::parse(&noncanon), Err(LockFileError::NotCanonical));
    // Empty lock (header only) with a valid hash.
    let empty_body = "aegis-allowlist-lock v1\nadapter x\nfamily sqlite\n";
    let empty = format!("{empty_body}sha256 {}\n", sha256_hex(empty_body.as_bytes()));
    assert_eq!(Allowlist::parse(&empty), Err(LockFileError::Empty));
}

fn kv_decl(extra: &str) -> String {
    format!(
        "aegis-allowlist-decl v1\nadapter kvdb\nfamily redis\nschema kv tenant=0 key=1 cols=0,1,2 permitted=1,2\n\
         op kv select eq(1) w=- r=-\n{extra}"
    )
}

fn kind_of(d: &str) -> Result<String, DeclErrorKind> {
    generate(d).map_err(|e| e.kind)
}

#[test]
fn denylisted_entries_are_refused() {
    assert!(kind_of(&kv_decl("")).is_ok());
    assert_eq!(kind_of(&kv_decl("op kv eval tt w=- r=-\n")), Err(DeclErrorKind::Denied("EVAL")));
    assert_eq!(kind_of(&kv_decl("op kv flushall tt w=- r=-\n")), Err(DeclErrorKind::Denied("FLUSHALL")));
    assert_eq!(kind_of(&kv_decl("op kv keys pfx(1) w=- r=-\n")), Err(DeclErrorKind::Denied("KEYS")));
    assert_eq!(kind_of(&kv_decl("op kv frobnicate tt w=- r=-\n")), Err(DeclErrorKind::Syntax));
    let valkey = kv_decl("op kv swapdb tt w=- r=-\n").replace("family redis", "family valkey");
    assert_eq!(kind_of(&valkey), Err(DeclErrorKind::Denied("SWAPDB")));
    let sql = "aegis-allowlist-decl v1\nadapter db\nfamily sqlite\nschema t tenant=0 key=1 cols=0,1 permitted=1\n";
    assert_eq!(kind_of(&format!("{sql}op t replace tt w=1 r=-\n")), Err(DeclErrorKind::Denied("REPLACE")));
    assert_eq!(kind_of(&format!("{sql}op t pragma tt w=- r=-\n")), Err(DeclErrorKind::Denied("PRAGMA")));
    let pg = sql.replace("family sqlite", "family postgres");
    assert_eq!(kind_of(&format!("{pg}op t merge tt w=1 r=-\n")), Err(DeclErrorKind::Denied("MERGE")));
    // The error carries the line number of the offending entry.
    assert_eq!(generate(&kv_decl("op kv eval tt w=- r=-\n")).map_err(|e| e.line), Err(6));
}

/// Oracle (P8-spec-001, DENY-M): each MariaDB keyword denylist item, as the kind token of a fixture-lock entry, is
/// refused as denied; the mandated op set (incl. both upsert forms) generates and verifies.
#[test]
fn mariadb_denylist_in_a_fixture_lock() {
    let my = "aegis-allowlist-decl v1\nadapter notes-mariadb\nfamily mariadb\nschema notes tenant=0 key=1 cols=0,1,2,3 permitted=1,2,3\n\
              op notes select eq(1) w=- r=1,2,3\nop notes insert tt w=1,2,3 r=1\nop notes update eq(1) w=2 r=-\n\
              op notes delete eq(1) w=- r=-\nop notes upsert tt w=1,2,3 r=1\nop notes upsert tt w=1 r=-\n";
    let lock = generate(my).unwrap_or_else(|e| unreachable!("{e:?}"));
    assert!(lock.starts_with("aegis-allowlist-lock v1\nadapter notes-mariadb\nfamily mariadb\n"), "{lock}");
    assert_eq!(verify(my, &lock), Ok(()));
    let Ok(al) = Allowlist::parse(&lock) else { unreachable!() };
    assert_eq!(al.family(), EngineFamily::Mariadb);
    let words: Vec<&str> = denylist(EngineFamily::Mariadb)
        .iter()
        .map(|d| d.item)
        .filter(|i| i.bytes().all(|c| c.is_ascii_alphabetic()))
        .collect();
    assert!(words.len() >= 10, "{words:?}");
    for w in words {
        let d = format!("{my}op notes {} tt w=1 r=-\n", w.to_ascii_lowercase());
        assert_eq!(kind_of(&d), Err(DeclErrorKind::Denied(w)), "{w}");
    }
    // The PostgreSQL upsert skeleton (ON CONFLICT DO) is never the MariaDB one: DO is denied there.
    assert!(denied(EngineFamily::Mariadb, "DO").is_some());
}

/// Oracle (P8-spec-001, DENY-M): every MariaDB denylist form in rendered statement text is refused.
#[test]
fn mariadb_rendered_sql_scanner() {
    let m = EngineFamily::Mariadb;
    let hit = |q: &str| denied_in_sql(m, q).map(|d| d.map(|e| e.item));
    let guard = "INSERT INTO `t` (`tenant`, `id`, `x`) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE `x` = \
                 IF(CAST(`tenant` AS BINARY) = CAST(VALUES(`tenant`) AS BINARY), VALUES(`x`), `x`)";
    // The monban-adapter-mysql mandated forms pass.
    for ok in [
        guard.to_string(),
        format!("{guard} RETURNING `id`, `x`"),
        format!(
            "{guard}, `y` = IF(CAST(`tenant` AS BINARY) = CAST(VALUES(`tenant`) AS BINARY), VALUES(`y`), `y`) RETURNING `id`"
        ),
        "INSERT INTO `t` (`tenant`, `id`) SELECT ?, ? FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `t` WHERE \
         CAST(`tenant` AS BINARY) = CAST(? AS BINARY)) RETURNING `id`"
            .to_string(),
        "SELECT `a`.`id` FROM `notes` AS `a` WHERE (`a`.`tenant` = ?) FOR UPDATE".to_string(),
        "SELECT 'REPLACE; @x' FROM `do` WHERE x = 'it\\'s' -- CALL p\n".to_string(),
        "SELECT \"@\" # LOAD DATA\n".to_string(),
        "SELECT 1 /* HANDLER ; */".to_string(),
        "SELECT `a``b` FROM t".to_string(),
    ] {
        assert_eq!(hit(&ok), Ok(None), "{ok}");
    }
    let cases: &[(&str, &str)] = &[
        ("REPLACE INTO t VALUES (1)", "REPLACE"),
        ("INSERT IGNORE INTO t VALUES (1)", "IGNORE"),
        ("LOAD DATA INFILE '/etc/passwd' INTO TABLE t", "LOAD"),
        ("SELECT * FROM t INTO OUTFILE '/tmp/x'", "OUTFILE"),
        ("SELECT * FROM t INTO DUMPFILE '/tmp/x'", "DUMPFILE"),
        ("HANDLER t OPEN", "HANDLER"),
        ("DO SLEEP(1)", "DO"),
        ("CALL p()", "CALL"),
        ("PREPARE s FROM 'x'", "PREPARE"),
        ("SET SESSION sql_mode = ''", "SESSION"),
        ("SELECT @x := 1", "@"),
        ("SELECT @@sql_mode", "@"),
        ("SELECT 1; SELECT 2", ";"),
        ("SELECT 1;", ";"),
        ("SELECT 1 /*! UNION SELECT 2 */", "/*!"),
        ("SELECT 1 /*M!100000 UNION SELECT 2 */", "/*!"),
        ("SELECT 1 --1", "--"),
        ("SELECT 1 --", "--"),
        ("INSERT INTO t (a) VALUES (?) ON DUPLICATE KEY UPDATE `a` = VALUES(`a`)", "ON DUPLICATE KEY UPDATE"),
        ("INSERT INTO t (a) VALUES (?) ON DUPLICATE KEY UPDATE", "ON DUPLICATE KEY UPDATE"),
        (
            "INSERT INTO t (a) VALUES (?) ON DUPLICATE KEY UPDATE `a` = IF(CAST(`a` AS BINARY) = CAST(VALUES(`a`) AS BINARY), VALUES(`a`), `a`)",
            "ON DUPLICATE KEY UPDATE",
        ),
        (
            "INSERT INTO t (a) VALUES (?) ON DUPLICATE KEY UPDATE `x` = IF(CAST(`t` AS BINARY) = CAST(VALUES(`u`) AS BINARY), VALUES(`x`), `x`)",
            "ON DUPLICATE KEY UPDATE",
        ),
        (
            "INSERT INTO t (a) VALUES (?) ON DUPLICATE KEY UPDATE `x` = IF(CAST(`t` AS BINARY) = CAST(VALUES(`t`) AS BINARY), VALUES(`x`), `y`)",
            "ON DUPLICATE KEY UPDATE",
        ),
        (&*Box::leak(format!("{guard}, `y` = 1").into_boxed_str()), "ON DUPLICATE KEY UPDATE"),
        (&*Box::leak(format!("{guard} WHERE 1").into_boxed_str()), "ON DUPLICATE KEY UPDATE"),
        ("SELECT DUPLICATE FROM t", "ON DUPLICATE KEY UPDATE"),
        ("SELECT 1 ON DUPLICATE x", "ON DUPLICATE KEY UPDATE"),
    ];
    for (q, item) in cases {
        assert_eq!(hit(q), Ok(Some(*item)), "{q}");
    }
    for q in ["SELECT 'open", "SELECT 'esc\\'", "SELECT \"x", "SELECT `x", "SELECT 1 /* open", "SELECT 'a\\"] {
        assert_eq!(hit(q), Err(Unterminated), "{q}");
    }
}

#[test]
fn shape_rules_are_enforced() {
    assert_eq!(kind_of(&kv_decl("op kv delete tt w=- r=-\n")), Err(DeclErrorKind::Kv(KvError::UnsupportedFilter)));
    assert_eq!(
        kind_of(&kv_decl("op kv select not(eq(1)) w=- r=-\n")),
        Err(DeclErrorKind::Schema(SchemaError::NotRequiresExact))
    );
    assert_eq!(kind_of(&kv_decl("op kv insert tt w=1 r=-\n")), Err(DeclErrorKind::Kv(KvError::UnsupportedWrite)));
    let sql =
        "aegis-allowlist-decl v1\nadapter db\nfamily postgres\nschema t tenant=0 key=1 cols=0,1,2 permitted=1,2\n";
    let k = |l: &str| kind_of(&format!("{sql}{l}\n"));
    assert!(k("op t select not(eq(2)) w=- r=1").is_ok(), "Not is fine on an exact SQL family");
    assert_eq!(k("op t select eq(9) w=- r=-"), Err(DeclErrorKind::Schema(SchemaError::UnknownField(9))));
    assert_eq!(k("op t select tt w=- r=0"), Err(DeclErrorKind::Schema(SchemaError::ReturningNotPermitted(0))));
    assert_eq!(k("op t update tt w=0 r=-"), Err(DeclErrorKind::Schema(SchemaError::TenantFieldWritten)));
    assert_eq!(k("op t update tt w=1 r=-"), Err(DeclErrorKind::Lower(LowerError::KeyWritten(1))));
    assert_eq!(k("op t insert tt w=2 r=-"), Err(DeclErrorKind::Lower(LowerError::MissingKey(1))));
    assert_eq!(k("op u select tt w=- r=-"), Err(DeclErrorKind::UnknownCollection));
    for bad in [
        "op t select tt w=- r=01",
        "op t select tt w=- r=",
        "op t select tt r=- w=-",
        "op t select tt  w=- r=-",
        "op t select tt w=- r=- ",
        "op t select eq(1 w=- r=-",
        "op t select and(tt) w=- r=-",
        "op t select tt() w=- r=-",
        "op T select tt w=- r=-",
        "op t Select tt w=- r=-",
        "op t select tt w=-1 r=-",
        "op t select tt w=- r=-\r",
        "nop",
    ] {
        assert_eq!(k(bad), Err(DeclErrorKind::Syntax), "{bad:?}");
    }
    assert_eq!(kind_of(sql), Err(DeclErrorKind::NoOps));
    assert_eq!(
        kind_of(&format!("{sql}schema t tenant=0 key=1 cols=0,1 permitted=1\nop t select tt w=- r=-\n")),
        Err(DeclErrorKind::DuplicateSchema)
    );
    for s in [
        "schema t tenant=0 key=0 cols=0,1 permitted=1",
        "schema t tenant=0 key=- cols=0,1 permitted=1",
        "schema t tenant=0 key=1 cols=0,1,1 permitted=1",
        "schema t tenant=0 key=2 cols=0,1 permitted=1",
        "schema t tenant=3 key=1 cols=0,1 permitted=1",
        "schema t tenant=0 key=1 cols=0,1 permitted=5",
    ] {
        let d = format!("aegis-allowlist-decl v1\nadapter db\nfamily sqlite\n{s}\nop t select tt w=- r=-\n");
        assert_eq!(kind_of(&d), Err(DeclErrorKind::Syntax), "{s}");
    }
    assert_eq!(kind_of("aegis-allowlist-decl v2\n").map_err(|_| ()), Err(()));
    assert_eq!(generate("aegis-allowlist-decl v1\nadapter Db\n").map_err(|e| e.kind), Err(DeclErrorKind::Adapter));
    assert_eq!(
        generate("aegis-allowlist-decl v1\nadapter db\nfamily mysql\n").map_err(|e| e.kind),
        Err(DeclErrorKind::Family)
    );
}

#[test]
fn runtime_allowlist_permits_by_shape_only() {
    let (_, lock) = pair("notes-pg");
    let Ok(al) = Allowlist::parse(&lock) else { unreachable!() };
    let tenant = TenantId::new(77).unwrap_or_else(|_| unreachable!());
    let mut op = Op {
        tenant,
        collection: "notes".into(),
        kind: OpKind::Select,
        filter: Pred::Eq(1, Value::Str("any value".into())),
        writes: vec![],
        returning: vec![3, 1, 2],
    };
    assert!(al.permits(&op));
    op.filter = Pred::Eq(1, Value::Int(123));
    assert!(al.permits(&op), "values are parameters");
    op.filter = Pred::Eq(2, Value::Int(123));
    assert!(!al.permits(&op), "other field");
    op.filter = Pred::Eq(1, Value::Int(1));
    op.returning = vec![1, 2];
    assert!(!al.permits(&op), "other projection");
    op.kind = OpKind::Delete;
    op.returning = vec![];
    assert!(al.permits(&op));
    op.collection = "x y".into();
    assert!(!al.permits(&op));
}

#[test]
fn rendered_sql_denylist_scanner() {
    let s = EngineFamily::Sqlite;
    let hit = |f, q: &str| denied_in_sql(f, q).map(|d| d.map(|e| e.item));
    assert_eq!(hit(s, "SELECT \"id\" FROM \"notes\" WHERE (\"t\" = ?)"), Ok(None));
    assert_eq!(hit(s, "SELECT 'ATTACH' FROM \"pragma\" WHERE x = 'it''s -- PRAGMA'"), Ok(None));
    assert_eq!(hit(s, "SELECT 1 -- PRAGMA\n"), Ok(None));
    assert_eq!(hit(s, "SELECT 1 /* attach */"), Ok(None));
    assert_eq!(hit(s, "attach database 'x' as y"), Ok(Some("ATTACH")));
    assert_eq!(hit(s, "INSERT OR REPLACE INTO t VALUES (1)"), Ok(Some("REPLACE")));
    assert_eq!(hit(s, "SELECT 1; Pragma writable_schema=1"), Ok(Some("PRAGMA")));
    assert_eq!(hit(s, "SELECT 'unterminated"), Err(Unterminated));
    assert_eq!(hit(s, "SELECT \"x"), Err(Unterminated));
    assert_eq!(hit(s, "SELECT 1 /* open"), Err(Unterminated));
    let pg = EngineFamily::Postgres;
    assert_eq!(
        hit(
            pg,
            "INSERT INTO t (a) VALUES ($1) ON CONFLICT (t, id) DO UPDATE SET a = excluded.a WHERE t.t = excluded.t COLLATE \"C\""
        ),
        Ok(None)
    );
    assert_eq!(hit(pg, "MERGE INTO t USING s ON true"), Ok(Some("MERGE")));
    assert_eq!(hit(pg, "SET SESSION role x"), Ok(Some("SESSION")));
}

#[test]
fn native_words_follow_the_statement_tree() {
    let tenant = TenantId::new(1).unwrap_or_else(|_| unreachable!());
    let kv = Schema {
        collection: "kv".into(),
        tenant_field: 0,
        columns: (0..3)
            .map(|f| Column {
                field: f,
                name: String::new(),
                nullable: f != 0,
                collation: Collation::Binary,
                key: f == 1,
            })
            .collect(),
        permitted: vec![1, 2],
        unique_indexes: vec![UniqueIndex { fields: vec![0, 1], prefix: false }],
    };
    let s = |v: &str| Value::Str(v.into());
    let op = |kind, filter, writes| Op { tenant, collection: "kv".into(), kind, filter, writes, returning: vec![] };
    let w = |o: &Op, f| native_words(f, o, &kv);
    assert_eq!(
        w(&op(OpKind::Select, Pred::Pfx(1, "a".into()), vec![]), EngineFamily::Redis),
        Ok(vec!["SCAN", "MATCH", "COUNT"])
    );
    assert_eq!(
        w(&op(OpKind::Insert, Pred::Tt, vec![(1, s("k")), (2, s("v"))]), EngineFamily::Valkey),
        Ok(vec!["SET", "NX"])
    );
    let up = op(OpKind::Upsert, Pred::Tt, vec![(1, s("k")), (2, s("v"))]);
    assert_eq!(
        w(&up, EngineFamily::Postgres),
        Ok(vec!["INSERT", "INTO", "VALUES", "ON", "CONFLICT", "DO", "UPDATE", "SET", "WHERE"])
    );
    let sel = op(OpKind::Select, Pred::Or(Box::new(Pred::Tt), Box::new(Pred::Not(Box::new(Pred::Ff)))), vec![]);
    assert_eq!(w(&sel, EngineFamily::Sqlite), Ok(vec!["SELECT", "FROM", "WHERE", "AND", "OR", "NOT"]));
    for f in EngineFamily::ALL {
        for words in [w(&sel, f), w(&up, f)].into_iter().flatten() {
            assert!(words.iter().all(|x| denied(f, x).is_none()), "{f:?} {words:?}");
        }
    }
}
